import sqlite3,json,re
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True); c.row_factory=sqlite3.Row
t=json.load(open('scratchpad/session_2026-11-21-identity-need-icf-triples/triples.json'))
idn={r['identity_code']:r for r in c.execute('select * from base_taxonomy_identity')}
need={r['need_code']:r for r in c.execute('select * from access_needs')}
icf={r['icf_code']:r for r in c.execute('select * from base_icf')}
links={r['link_id']:r for r in c.execute('select * from identity_icf_map')}
nmap={(r['need_code'],r['icf_code']):r for r in c.execute('select * from access_need_icf')}
seenw=set()
for x in t:
    I,N,C,w=x['identity'],x['need'],x['icf'],x['warrant']
    m=re.search(r'Need (\S+) registry text: "(.*?)"\. Identity (\S+): "(.*?)"\. Code (\S+): (.*)$',w)
    assert m,(I,N,C,w)
    n2,qn,i2,qi,c2,tail=m.groups()
    assert (n2,i2,c2)==(N,I,C),(I,N,C)
    where=[k for k in ('absorbs','design_obligation','notes') if need[N][k] and qn in need[N][k]]
    iw=[k for k in ('display_name','description') if idn[I][k] and qi in idn[I][k]]
    prob=[]
    if 'absorbs' not in where: prob.append(f'need quote not in absorbs: {where}')
    if not iw: prob.append('identity quote absent')
    if x['support'] in('need','both') and (N,C) not in nmap: prob.append('need map lacks code')
    ids=[int(a) for a in re.findall(r'link ([\d/]+)',tail)[0].split('/')] if 'link' in tail else []
    for l in ids:
        L=links[l]
        if (L['identity_code'],L['icf_code'])!=(I,C) or L['retired_at']: prob.append(f'link {l} wrong')
    live=[r['link_id'] for r in links.values() if (r['identity_code'],r['icf_code'])==(I,C) and not r['retired_at']]
    if x['support']!='need' and sorted(ids)!=sorted(live): prob.append(f'ids {ids} vs live {live}')
    if x['support']=='need' and live: prob.append(f'NOTE identity map ALSO holds {C} links {live} but tail says need only')
    if x['support']=='ground':
        word=re.search(r'the word "(.*?)"',tail).group(1).lower()
        inm=[l for l in ids if word in links[l]['mechanism'].lower()]
        intitle= word in (icf[C]['title'] or '').lower()
        ncells={k:need[N][k] for k in ('absorbs','design_obligation','notes') if need[N][k] and word in need[N][k].lower()}
        nicf={k[1]:r['notes'] for k,r in nmap.items() if k[0]==N and r['notes'] and word in r['notes'].lower()}
        # other codes of same identity sharing mechanism containing word
        others=sorted({r['icf_code'] for r in links.values() if r['identity_code']==I and not r['retired_at'] and word in r['mechanism'].lower()})
        print(f"GROUND {I}|{N}|{C} word={word!r} links={ids} in_mech_of={inm} in_title={intitle} title={icf[C]['title']!r}\n    need cells: { {k:re.findall(r'[^,;.]*'+re.escape(word)+r'[^,;.]*',v,flags=re.I) for k,v in ncells.items()} } icfnotes={nicf}\n    identity codes whose mechanism holds the word: {others}")
    for p in prob: print('PROBLEM',I,N,C,p)
print('checked',len(t))
# why-sentence uniqueness
whys=sorted({x['warrant'].split(' Need ')[0] for x in t})
print(len(whys)); [print(' -',w) for w in whys]
import pathlib
s=pathlib.Path('references/website/data/populations.json').read_text()
print('populations.json has quote:', "stroke sequelae (unilateral neglect, navigation impairment, aphasia, hemiplegia)" in s)
i=s.find('stroke sequelae'); print(s[max(0,i-900):i+200])
