c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True); c.row_factory=sqlite3.Row
t=json.load(open('scratchpad/session_2026-11-21-identity-need-icf-triples/triples.json'))
have={(x['identity'],x['need'],x['icf']) for x in t}
pairs=sorted({(x['identity'],x['need']) for x in t})
need={r['need_code']:r for r in c.execute('select * from access_needs')}
icf={r['icf_code']:r for r in c.execute('select * from base_icf')}
imap={}
for r in c.execute('select * from identity_icf_map where retired_at is null'): imap.setdefault(r['identity_code'],{}).setdefault(r['icf_code'],[]).append(r)
nn={}
for r in c.execute('select * from access_need_icf'): nn.setdefault(r['need_code'],{})[r['icf_code']]=r
stop=set('with that this from their people users'.split())
def toks(s): return {w for w in re.findall(r'[a-z]{4,}',s.lower())}-stop
def ntext(N): return ' | '.join(filter(None,[need[N]['absorbs'],need[N]['design_obligation'],need[N]['notes']]+[r['notes'] for r in nn.get(N,{}).values()]))
print("== within judged pairs: identity-map codes NOT attached, with words (>=4 letters; prefix match 5) shared under the generator's own rule")
for I,N in pairs:
    nt=ntext(N).lower(); 
    for C,ls in sorted(imap.get(I,{}).items()):
        if (I,N,C) in have: continue
        iside=' '.join([l['mechanism'] for l in ls]+[icf[C]['title'] or ''])
        sh=sorted(w for w in toks(iside) if w in nt)
        # stems
        st=sorted({w[:5] for w in toks(iside) if len(w)>=6 and w[:5] in nt}-{w[:5] for w in sh})
        if sh or st: print(f"  {I}|{N}|{C} links={[l['link_id'] for l in ls]} shared={sh} stems={st}")
print("== all identity x need NOT judged: shared tokens between identity name/description and need absorbs")
ids={r['identity_code']:r for r in c.execute("select * from base_taxonomy_identity where status='active'")}
for I,r in ids.items():
    it=toks((r['display_name'] or '')+' '+(r['description'] or ''))
    for N in need:
        if (I,N) in pairs: continue
        ab=(need[N]['absorbs'] or '').lower()+' '+(need[N]['notes'] or '').lower()
        sh=sorted(w for w in it if w in ab)
        if sh or N in ((r['description'] or '')): print(f"  {I} x {N}: {sh}  desc-names-need={N in (r['description'] or '')}")
